import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 첨부파일 소유 대상 유형 값 (schema.sql에 값 목록이 없다)
const OWNER_APPROVAL = 'approval_document';
const OWNER_POST = 'post';
// 가정: 첨부파일 검색 대상 형식은 오피스·PDF 문서 (결정 Q-028)
const SEARCHABLE_EXT = "('hwp','doc','docx','xls','xlsx','ppt','pptx','pdf')";
const CATEGORIES = ['전자결재', '게시판', '일정관리', '문서함'];
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

// 가정: 결재문서는 기안자 본인 또는 보안문서가 아닌 상신 이후 문서만 보인다
const SCOPE_DOC = `(d.drafter_id = CAST(:userId AS bigint) OR (d.is_secret = false AND d.approval_status <> '기안'))`;
// 가정: 게시물은 전체 공개, 본인 작성, 작성자와 같은 부서의 부서 공개만 보인다
const SCOPE_POST = `(p.visibility_scope = 'ALL'
  OR p.author_id = CAST(:userId AS bigint)
  OR (p.visibility_scope = 'DEPARTMENT' AND EXISTS (
    SELECT 1 FROM employee au JOIN employee me ON me.department_id = au.department_id
    WHERE au.employee_id = p.author_id AND me.employee_id = CAST(:userId AS bigint))))`;

const RESULTS_CTE = `WITH r AS (
  SELECT '전자결재' AS category, d.approval_document_id AS "resultId", d.title AS title,
    CAST(NULL AS bigint) AS "attachmentId", CAST(NULL AS varchar) AS "fileName"
  FROM approval_document d
  WHERE ${SCOPE_DOC} AND (d.title ILIKE :pattern OR COALESCE(d.body, '') ILIKE :pattern)
  UNION ALL
  SELECT '게시판' AS category, p.post_id AS "resultId", p.title AS title,
    CAST(NULL AS bigint) AS "attachmentId", CAST(NULL AS varchar) AS "fileName"
  FROM post p
  WHERE ${SCOPE_POST} AND (p.title ILIKE :pattern OR p.content ILIKE :pattern)
  UNION ALL
  SELECT '전자결재' AS category, d.approval_document_id AS "resultId", d.title AS title,
    a.attachment_id AS "attachmentId", a.file_name AS "fileName"
  FROM attachment a
  JOIN approval_document d ON a.owner_type = '${OWNER_APPROVAL}' AND a.owner_id = d.approval_document_id
  WHERE CAST(:withAttachments AS boolean) = true AND ${SCOPE_DOC}
    AND a.file_name ILIKE :pattern AND lower(a.file_ext) IN ${SEARCHABLE_EXT}
  UNION ALL
  SELECT '게시판' AS category, p.post_id AS "resultId", p.title AS title,
    a.attachment_id AS "attachmentId", a.file_name AS "fileName"
  FROM attachment a
  JOIN post p ON a.owner_type = '${OWNER_POST}' AND a.owner_id = p.post_id
  WHERE CAST(:withAttachments AS boolean) = true AND ${SCOPE_POST}
    AND a.file_name ILIKE :pattern AND lower(a.file_ext) IN ${SEARCHABLE_EXT}
),
c AS (
  SELECT category, COUNT(*) AS cnt FROM r GROUP BY category
)
`;

const FILTER = `(CAST(:category AS text) IS NULL OR r.category = CAST(:category AS text))`;

@Controller('api/v1')
export class FnSfr03901Controller {
  @Get('/integrated-searches')
  async searchIntegrated(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const query = checks.queryOf(req.query);
    const keyword = String(query['keyword'] ?? '').trim();
    if (keyword === '') {
      throw new ApiError(422, 'SEARCH_KEYWORD_REQUIRED', '검색어를 입력해 주세요.');
    }
    const categoryRaw = String(query['category'] ?? '').trim();
    if (categoryRaw !== '' && !CATEGORIES.includes(categoryRaw)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '카테고리는 전자결재, 게시판, 일정관리, 문서함 중 하나여야 합니다.');
    }
    const attachRaw = String(query['includeAttachments'] ?? 'false').trim();
    if (attachRaw !== 'true' && attachRaw !== 'false' && attachRaw !== '') {
      throw new ApiError(400, 'VALIDATION_FAILED', '첨부파일 포함 여부는 true 또는 false여야 합니다.');
    }
    const page = query['page'] === undefined || query['page'] === '' ? 0 : Number(query['page']);
    let size = query['size'] === undefined || query['size'] === '' ? DEFAULT_SIZE : Number(query['size']);
    if (!Number.isInteger(page) || page < 0 || !Number.isInteger(size) || size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호와 쪽 크기가 올바르지 않습니다.');
    }
    if (size > MAX_SIZE) {
      size = MAX_SIZE;
    }
    const escaped = keyword.replace(/[\\%_]/g, (ch) => '\\' + ch);
    const params = {
      userId: user.id,
      pattern: '%' + escaped + '%',
      withAttachments: attachRaw === 'true' ? 'true' : 'false',
      category: categoryRaw === '' ? null : categoryRaw,
    };
    try {
      return await transaction(async (db) => {
        const items = await db.query(
          RESULTS_CTE +
            `SELECT r.category AS category, CAST(c.cnt AS integer) AS count, r."resultId" AS "resultId",
  r.title AS title, r."attachmentId" AS "attachmentId", r."fileName" AS "fileName"
FROM r JOIN c ON c.category = r.category
WHERE ${FILTER}
ORDER BY r.category, r."resultId" DESC, r."attachmentId"
LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)`,
          { ...params, size, offset: page * size },
        );
        const totals = await db.query(
          RESULTS_CTE + `SELECT COUNT(*) AS total FROM r WHERE ${FILTER}`,
          params,
        );
        const total = totals.length > 0 ? Number(totals[0]['total']) : 0;
        return { items, page, size, total };
      });
    } catch (e) {
      if (e instanceof ApiError) {
        throw e;
      }
      throw new ApiError(502, 'SEARCH_INDEX_FAILED', '검색 색인 처리 중 오류가 발생했습니다.');
    }
  }
}

