import { useState } from 'react';
import {
  call,
  useData,
  Num,
  Badge,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Tiles,
  Field,
  TextInput,
  Select,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const CATEGORIES = ['전자결재', '게시판', '일정관리', '문서함'];
const SIZE = 20;

export default function FnSfr03901Page({ role, notify }: PageProps) {
  const [keyword, setKeyword] = useState('');
  const [category, setCategory] = useState('');
  const [attach, setAttach] = useState('false');
  const [applied, setApplied] = useState<Row | null>(null);
  const [page, setPage] = useState(0);
  const [message, setMessage] = useState('');
  const [selected, setSelected] = useState<Row | null>(null);

  const list = useData<Page | undefined>(async () => {
    if (!applied) {
      return undefined;
    }
    return call<Page>('GET', '/integrated-searches', role, undefined, { ...applied, page, size: SIZE });
  }, [applied, page]);

  const summary = useData<Page | undefined>(async () => {
    if (!applied) {
      return undefined;
    }
    return call<Page>('GET', '/integrated-searches', role, undefined, {
      keyword: applied['keyword'],
      includeAttachments: applied['includeAttachments'],
      page: 0,
      size: 200,
    });
  }, [applied]);

  function search() {
    if (keyword.trim() === '') {
      setMessage('검색어를 입력해 주세요.');
      return;
    }
    setMessage('');
    setPage(0);
    setApplied({ keyword: keyword.trim(), category, includeAttachments: attach });
    notify('검색했습니다.');
  }

  function reset() {
    setKeyword('');
    setCategory('');
    setAttach('false');
    setApplied(null);
    setMessage('');
    setPage(0);
  }

  function countOf(name: string): number {
    const found = (summary.data?.items ?? []).find((r) => r['category'] === name);
    return found ? Number(found['count']) : 0;
  }

  const rows = list.data?.items ?? [];

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>카테고리별 건수</h2>
        <Tiles items={CATEGORIES.map((name): [string, React.ReactNode] => [name, <Num value={countOf(name)} />])} />
      </section>
      <section className="box span-12">
        <h2>통합검색 결과</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="검색어" required>
            <TextInput value={keyword} onChange={setKeyword} placeholder="검색어를 입력하세요" />
          </Field>
          <Field label="카테고리">
            <Select
              value={category}
              onChange={setCategory}
              options={CATEGORIES.map((name): [string, string] => [name, name])}
              placeholder="전체"
            />
          </Field>
          <Field label="첨부파일 내용 검색 포함 여부">
            <Select
              value={attach}
              onChange={setAttach}
              options={[['true', '포함'], ['false', '포함 안 함']]}
              placeholder="포함 안 함"
            />
          </Field>
        </Filters>
        {message !== '' && <ErrorText text={message} />}
        {list.error !== '' && <ErrorText text={list.error} />}
        <Band total={list.data?.total} />
        <DataTable
          columns={[
            { key: 'category', label: '검색 결과 카테고리', render: (r) => <Badge value={r['category']} /> },
            { key: 'title', label: '결과 제목' },
            { key: 'fileName', label: '파일명' },
            { key: 'count', label: '카테고리별 결과 건수', render: (r) => <Num value={r['count']} /> },
          ]}
          rows={rows}
          onRowClick={(r) => setSelected(r)}
          empty={applied ? '검색 결과가 없습니다.' : '검색어를 입력하고 조회하세요.'}
        />
        <Pager page={page} size={SIZE} total={list.data?.total ?? 0} onPage={setPage} />
      </section>
      {selected && (
        <Drawer title="검색 결과 상세" onClose={() => setSelected(null)}>
          <Pairs
            items={[
              ['검색 결과 카테고리', <Badge value={selected['category']} />],
              ['결과 항목 ID', <Num value={selected['resultId']} />],
              ['결과 제목', String(selected['title'] ?? '')],
              ['첨부파일 ID', selected['attachmentId'] == null ? '-' : <Num value={selected['attachmentId']} />],
              ['파일명', String(selected['fileName'] ?? '-')],
            ]}
          />
        </Drawer>
      )}
    </div>
  );
}
